def find_first_occurrence(arr, target):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            # Check if this is the first occurrence by looking at the previous element
            if mid > 0 and arr[mid-1] != target:
                return mid
            else:
                # Move left to find an earlier occurrence
                right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

